mapper.select:
SELECT distinct BOND.SEC_ID AS secId, BOND.VALUE_DATE AS valueDate, FIN.FINPROD_ABBR AS finprodAbbr, BOND.LAST_PERIOD AS lastPeriod, BOND.PRICE AS price, BOND.NETPRICE AS netprice, BOND.M_DURATION AS mDuration, BOND.M_CONVEXITY AS mConvexity, BOND.BPVALUE AS bpvalue, BOND.SDURATION AS sduration, BOND.SCNVXTY AS scnvxty, BOND.INTEREST_DURATION AS interestDuration, BOND.INTEREST_CNVXTY AS interestCnvxty, BOND.VALUE_SOURCE valueSource,
BOND.BPYIELD*100 AS bpyield, BOND.CREATE_TIME importDay, to_char(BOND.CREATE_TIME,'yyyy-MM-dd') importDayStr FROM MST_BOND_VALUATION_INFO BOND left join FIN_PRODUCT FIN on FIN.FINPROD_MARKET_ID = BOND.SEC_ID WHERE FIN.FINPROD_TYPE2 = #{FINPROD_TYPE_F01}
AND BOND.SEC_ID LIKE CONCAT(CONCAT('%',#{secId}),'%')
AND FIN.FINPROD_ABBR LIKE CONCAT(CONCAT('%',#{finprodAbbr}),'%')
AND BOND.VALUE_DATE = to_date(#{valueDate},'yyyy-mm-dd')
AND BOND.VALUE_SOURCE = #{valueSource}

SELECT distinct BOND.SEC_ID AS code, FIN.FINPROD_ABBR AS shortName FROM FIN_PRODUCT FIN LEFT JOIN MST_BOND_VALUATION_INFO BOND ON FIN.FINPROD_MARKET_ID = BOND.SEC_ID
FIN.FINPROD_TYPE2 = #{FINPROD_TYPE_F01}
and FIN.FINPROD_ABBR LIKE CONCAT(#{finprodAbbr,jdbcType=VARCHAR},'%')

select 	A.SEC_ID  secId
from MST_BOND_VALUATION_INFO A
where
	A.SEC_ID  =	#{secId,jdbcType=VARCHAR}
AND
	A.VALUE_DATE = #{valueDate,jdbcType=DATE}
AND
	A.VALUE_SOURCE=#{valueSource,jdbcType=VARCHAR}

select 	A.FINPROD_MARKET_ID  secId
from fin_product A
where
	A.FINPROD_MARKET_ID  =	#{secId,jdbcType=VARCHAR}
AND
	A.FINPROD_TYPE2 = #{prodType2,jdbcType=VARCHAR}

select 	A.FINPROD_MARKET_ID  secId
from fin_product A
where
	A.FINPROD_MARKET_ID  =	#{secId,jdbcType=VARCHAR}
AND
	A.FINPROD_TYPE2 = #{prodType2,jdbcType=VARCHAR}
AND
	A.FINPROD_ABBR = #{secName,jdbcType=VARCHAR}
